  kind: Artifact["kind"];
  reason: string;
};

type PathValidation =
  | { ok: true; realPath: string; sizeBytes: number; dev: number; ino: number }
  | { ok: false; reason: string };

type ScanResult = {
  candidates: Candidate[];
  rejected: RejectedEntry[];
