  depthLimitedDirectories: number;
  unreadableDirectories: number;
};

function comparePath(left: string, right: string): number {
  return left === right ? 0 : left < right ? -1 : 1;
}

function isWithinRoot(rootReal: string, candidateReal: string): boolean {
  const relative = path.relative(rootReal, candidateReal);
  return relative === "" || (!relative.startsWith("..") && !path.isAbsolute(relative));
}

function skillLocation(relativePath: string): {
  skillRoot: typeof SKILL_ROOTS[number];
  directoryDepth: number;
} | null {
  const normalized = relativePath.replaceAll("\\", "/");
  const lower = normalized.toLowerCase();
  for (const skillRoot of SKILL_ROOTS) {
    const prefix = `${skillRoot.toLowerCase()}/`;
    if (!lower.startsWith(prefix) || path.posix.basename(lower) !== "skill.md") continue;
    const parent = path.posix.dirname(normalized.slice(prefix.length));
    return {
      skillRoot,
      directoryDepth: parent === "." ? 0 : parent.split("/").length,
    };
  }
  return null;
}

async function validatePath(rootReal: string, target: string, expected: "file" | "directory"): Promise<PathValidation> {
  try {
    const metadata = await lstat(target);
    if (metadata.isSymbolicLink()) return { ok: false, reason: "repo_docs_symbolic_link" };
    if (expected === "file" ? !metadata.isFile() : !metadata.isDirectory()) {
      return { ok: false, reason: "repo_docs_unsupported_entry_type" };
    }
    const targetReal = await realpath(target);
    if (!isWithinRoot(rootReal, targetReal)) return { ok: false, reason: "repo_docs_path_outside_root" };
    return {
      ok: true,
      realPath: targetReal,
      sizeBytes: metadata.size,
      dev: metadata.dev,
      ino: metadata.ino,
    };
  } catch {
    return { ok: false, reason: "repo_docs_unreadable" };
  }
}

function rejectedEntry(
  absolutePath: string,
  relativePath: string,
  kind: Artifact["kind"],
  reason: string,
): RejectedEntry {
  return { absolutePath, relativePath, kind, reason };
}

async function scanRepository(rootReal: string): Promise<ScanResult> {
  const candidates: Candidate[] = [];
  const rejected: RejectedEntry[] = [];
  const queue: Array<{ absolutePath: string; relativePath: string; depth: number }> = [{
    absolutePath: rootReal,
    relativePath: "",
    depth: 0,
  }];
  let scannedEntries = 0;
  let scanTruncated = false;
  let depthLimitedDirectories = 0;
  let unreadableDirectories = 0;

  while (queue.length > 0 && !scanTruncated) {
    queue.sort((left, right) => comparePath(left.relativePath, right.relativePath));
    const directory = queue.shift();
    if (directory === undefined) break;
    const validation = await validatePath(rootReal, directory.absolutePath, "directory");
    if (!validation.ok) {
      unreadableDirectories += 1;
      rejected.push(rejectedEntry(
        directory.absolutePath,
        directory.relativePath || ".",
        "directory",
        validation.reason,
      ));
      continue;
    }

    let entries;
    try {
      entries = await readdir(directory.absolutePath, { withFileTypes: true });
    } catch {
      unreadableDirectories += 1;
      rejected.push(rejectedEntry(
        directory.absolutePath,
        directory.relativePath || ".",
        "directory",
        "repo_docs_unreadable",
      ));
      continue;
    }
    entries.sort((left, right) => comparePath(left.name.normalize("NFC"), right.name.normalize("NFC")));

    for (const entry of entries) {
      if (scannedEntries >= REPO_DOCS_LIMITS.maxScannedEntries) {
        scanTruncated = true;
        break;
      }
      scannedEntries += 1;
      const absolutePath = path.join(directory.absolutePath, entry.name);
      const relativePath = relativePortablePath(rootReal, absolutePath).normalize("NFC");

      if (entry.isSymbolicLink()) {
        rejected.push(rejectedEntry(absolutePath, relativePath, "other", "repo_docs_symbolic_link"));
        continue;
      }
      if (entry.isDirectory()) {
        if (SKIPPED_DIRECTORIES.has(entry.name.toLowerCase())) continue;
        const depth = directory.depth + 1;
        if (depth > REPO_DOCS_LIMITS.maxRepositoryDepth) {
          depthLimitedDirectories += 1;
          rejected.push(rejectedEntry(absolutePath, relativePath, "directory", "repo_docs_repository_depth_limit"));
          continue;
        }
        queue.push({ absolutePath, relativePath, depth });
        continue;
      }
      if (!entry.isFile()) continue;
      if (entry.name.toLowerCase() === "agents.md") {
        candidates.push({ category: "agents", absolutePath, relativePath });
      }
      const location = skillLocation(relativePath);
      if (location !== null) {
        if (location.directoryDepth > REPO_DOCS_LIMITS.maxSkillDepth) {
          rejected.push(rejectedEntry(absolutePath, relativePath, "other", "repo_docs_skill_depth_limit"));
        } else {
          candidates.push({ category: "skill", absolutePath, relativePath, ...location });
        }
      }
    }
  }

  return {
    candidates: candidates.sort((left, right) => comparePath(left.relativePath, right.relativePath)),
    rejected,
    scannedEntries,
    scanTruncated,
    depthLimitedDirectories,
    unreadableDirectories,
  };
}

function completeUtf8PrefixLength(buffer: Buffer): number {
  if (buffer.length === 0) return 0;
  let leadIndex = buffer.length - 1;
  while (leadIndex >= 0 && ((buffer[leadIndex] ?? 0) & 0xc0) === 0x80) leadIndex -= 1;
  if (leadIndex < 0) return 0;
  const lead = buffer[leadIndex] ?? 0;
  const expected = lead < 0x80 ? 1 : lead < 0xe0 ? 2 : lead < 0xf0 ? 3 : lead < 0xf8 ? 4 : 1;
  const available = buffer.length - leadIndex;
  return available < expected ? leadIndex : buffer.length;
}

function countReturnedLines(text: string): number {
  if (text.length === 0) return 0;
  const newlines = text.match(/\r\n|\r|\n/g)?.length ?? 0;
  return newlines + (/\r\n$|[\r\n]$/.test(text) ? 0 : 1);
}

async function readAgentsDocument(
  rootReal: string,
  target: string,
): Promise<{ ok: true; data: RepositoryAgentsDocumentEvidence } | { ok: false; reason: string }> {
  const before = await validatePath(rootReal, target, "file");
  if (!before.ok) return before;
  let handle;
  try {
    handle = await open(target, "r");
    const opened = await handle.stat();
    if (!opened.isFile() || !sameFileIdentity(opened, before)) {
      return { ok: false, reason: "repo_docs_file_changed_during_read" };
    }
    const requestedBytes = Math.min(opened.size, REPO_DOCS_LIMITS.maxAgentsDocumentBytes);
    const buffer = Buffer.alloc(requestedBytes);
    let bytesRead = 0;
    while (bytesRead < requestedBytes) {
      const chunk = await handle.read(buffer, bytesRead, requestedBytes - bytesRead, bytesRead);
      if (chunk.bytesRead === 0) break;
      bytesRead += chunk.bytesRead;
    }
    const afterHandle = await handle.stat();
    const afterPath = await validatePath(rootReal, target, "file");
    if (
      !afterPath.ok
      || !sameFileIdentity(afterHandle, before)
      || !sameFileIdentity(afterPath, before)
      || afterHandle.size !== opened.size
      || afterHandle.mtimeMs !== opened.mtimeMs
    ) {
      return { ok: false, reason: "repo_docs_file_changed_during_read" };
    }
    const readBuffer = buffer.subarray(0, bytesRead);
    const completeBytes = completeUtf8PrefixLength(readBuffer);
    const text = readBuffer.subarray(0, completeBytes).toString("utf8");
    const truncated = afterHandle.size > completeBytes;
    return {
      ok: true,
      data: {
        fileSizeBytes: afterHandle.size,
        returnedBytes: completeBytes,
        returnedLines: countReturnedLines(text),
        truncated,
        endsMidLine: truncated && text.length > 0 && !/[\r\n]$/.test(text),
        text,
      },
    };
  } catch {
    return { ok: false, reason: "repo_docs_unreadable" };
  } finally {
    await handle?.close();
  }
}

function artifactForCandidate(candidate: Candidate, sizeBytes: number): Artifact {
  return {
    id: artifactId(candidate.relativePath),
    path: candidate.absolutePath,
    relativePath: candidate.relativePath,
    kind: "other",
    status: "selected",
    sizeBytes,
  };
}

function sourceForArtifact(artifact: Artifact, line?: number, endLine?: number): EvidenceSource {
  return {
    artifactId: artifact.id,
    path: artifact.relativePath,
    ...(line === undefined ? {} : { line }),
    ...(endLine === undefined ? {} : { endLine }),
  };
}

function rejectionArtifact(entry: RejectedEntry): Artifact {
  return {
    id: artifactId(entry.relativePath),
    path: entry.absolutePath,
    relativePath: entry.relativePath,
    kind: entry.kind,
    status: "skipped",
    reason: entry.reason,
  };
}

function warningForRejected(reason: string, count: number): InspectionWarning {
  return {
    code: reason,
    message: `${count} repository entr${count === 1 ? "y was" : "ies were"} skipped (${reason}).`,
  };
}

export async function inspectRepositoryDocs(sourceRoot: string): Promise<RepositoryDocsResult> {
  const resolved = path.resolve(sourceRoot);
  let rootMetadata;
  try {
    rootMetadata = await lstat(resolved);
  } catch (error: unknown) {
    if (isMissingPathError(error)) throw new UsageError(`Input path not found: ${resolved}`);
    throw error;
  }
  if (rootMetadata.isSymbolicLink() || !rootMetadata.isDirectory()) {
    throw new UsageError(`Repository docs source is not a non-symbolic directory: ${resolved}`);
  }
  const rootReal = await realpath(resolved);
  const scan = await scanRepository(rootReal);
  const agentsCandidates = scan.candidates.filter((item) => item.category === "agents");
  const skillCandidates = scan.candidates.filter((item): item is Candidate & { category: "skill" } =>
    item.category === "skill");
  const selectedAgents = agentsCandidates.slice(0, REPO_DOCS_LIMITS.maxAgentsDocuments);
  const selectedSkills = skillCandidates.slice(0, REPO_DOCS_LIMITS.maxSkillFiles);
  const agentsDocumentsOmitted = Math.max(0, agentsCandidates.length - selectedAgents.length);
  const skillFilesOmitted = Math.max(0, skillCandidates.length - selectedSkills.length);
  const omissionsUnknown = scan.scanTruncated || scan.depthLimitedDirectories > 0 || scan.unreadableDirectories > 0;

  const ledger = new EvidenceLedger();
  const artifactMap = new Map<string, Artifact>();
  const rejectedCounts = new Map<string, number>();
  const addRejected = (entry: RejectedEntry): void => {
    artifactMap.set(entry.relativePath, rejectionArtifact(entry));
    rejectedCounts.set(entry.reason, (rejectedCounts.get(entry.reason) ?? 0) + 1);
  };
  for (const entry of scan.rejected) addRejected(entry);
  for (const candidate of agentsCandidates.slice(REPO_DOCS_LIMITS.maxAgentsDocuments)) {
    artifactMap.set(candidate.relativePath, {
      id: artifactId(candidate.relativePath),
      path: candidate.absolutePath,
      relativePath: candidate.relativePath,
      kind: "other",
      status: "skipped",
      reason: "repo_docs_agents_file_limit",
    });
  }
  for (const candidate of skillCandidates.slice(REPO_DOCS_LIMITS.maxSkillFiles)) {
    artifactMap.set(candidate.relativePath, {
      id: artifactId(candidate.relativePath),
      path: candidate.absolutePath,
      relativePath: candidate.relativePath,
      kind: "other",
      status: "skipped",
      reason: "repo_docs_skill_file_limit",
    });
  }

  const agentsDocumentEvidenceIds: string[] = [];
  const skillFileEvidenceIds: string[] = [];
  let agentsDocumentsTruncated = 0;
  for (const candidate of selectedAgents) {
    const read = await readAgentsDocument(rootReal, candidate.absolutePath);
    if (!read.ok) {
      addRejected(rejectedEntry(candidate.absolutePath, candidate.relativePath, "other", read.reason));
      continue;
    }
    const artifact = artifactForCandidate(candidate, read.data.fileSizeBytes);
    artifactMap.set(candidate.relativePath, artifact);
    if (read.data.truncated) agentsDocumentsTruncated += 1;
    const evidence = ledger.add(
      "repo_docs.agents_document",
      `Repository instructions document ${candidate.relativePath}${read.data.truncated ? " (truncated)" : ""}.`,
      sourceForArtifact(artifact, 1, Math.max(1, read.data.returnedLines)),
      read.data,
    );
    agentsDocumentEvidenceIds.push(evidence.id);
  }

  for (const candidate of selectedSkills) {
    const validation = await validatePath(rootReal, candidate.absolutePath, "file");
    if (!validation.ok) {
      addRejected(rejectedEntry(candidate.absolutePath, candidate.relativePath, "other", validation.reason));
      continue;
    }
    const artifact = artifactForCandidate(candidate, validation.sizeBytes);
    artifactMap.set(candidate.relativePath, artifact);
    const evidence = ledger.add<RepositorySkillFileEvidence>(
      "repo_docs.skill_file",
      `Repository skill file ${candidate.relativePath}.`,
      sourceForArtifact(artifact),
      {
        fileSizeBytes: validation.sizeBytes,
        skillRoot: candidate.skillRoot,
        directoryDepth: candidate.directoryDepth,
      },
    );
    skillFileEvidenceIds.push(evidence.id);
  }

  const warnings: InspectionWarning[] = [...rejectedCounts.entries()]
    .sort(([left], [right]) => comparePath(left, right))
    .map(([reason, count]) => warningForRejected(reason, count));
  if (scan.scanTruncated) {
    warnings.push({
      code: "repo_docs_scan_truncated",
      message: `Repository documentation discovery stopped after ${REPO_DOCS_LIMITS.maxScannedEntries} entries; additional omissions are unknown.`,
    });
  }
  if (agentsDocumentsOmitted > 0 || omissionsUnknown) {
    warnings.push({
      code: "repo_docs_agents_truncated",
      message: `${agentsDocumentsOmitted} discovered AGENTS.md file(s) were omitted by the ${REPO_DOCS_LIMITS.maxAgentsDocuments}-file limit${omissionsUnknown ? "; additional omissions may be unknown" : ""}.`,
    });
  }
  if (skillFilesOmitted > 0 || omissionsUnknown) {
    warnings.push({
      code: "repo_docs_skills_truncated",
      message: `${skillFilesOmitted} discovered SKILL.md file(s) were omitted by the ${REPO_DOCS_LIMITS.maxSkillFiles}-file limit${omissionsUnknown ? "; additional omissions may be unknown" : ""}.`,
    });
  }

  const artifacts = [...artifactMap.values()].sort((left, right) =>
    comparePath(left.relativePath, right.relativePath));
  const evidence = ledger.values();
  return {
    schemaVersion: EVIDENCE_SCHEMA_VERSION,
    kind: REPO_DOCS_KIND,
    generatedAt: new Date().toISOString(),
    input: { path: rootReal },
    artifacts,
    coverage: coverageAnnotation(artifacts, rootReal),
    evidence,
    missingEvidence: [],
    warnings,
    statistics: {
      scannedEntries: scan.scannedEntries,
      agentsDocumentsFound: agentsCandidates.length,
      agentsDocumentsSelected: agentsDocumentEvidenceIds.length,
      agentsDocumentsTruncated,
      agentsDocumentsOmitted,
      skillFilesFound: skillCandidates.length,
      skillFilesSelected: skillFileEvidenceIds.length,
      skillFilesOmitted,
      scanTruncated: scan.scanTruncated ? 1 : 0,
      omissionsUnknown: omissionsUnknown ? 1 : 0,
    },
    details: {
      agentsDocumentEvidenceIds,
      skillFileEvidenceIds,
      limits: REPO_DOCS_LIMITS,
      scan: {
        scannedEntries: scan.scannedEntries,
        truncated: scan.scanTruncated,
        omissionsUnknown,
        agentsDocumentsOmitted,
        skillFilesOmitted,
      },
    },
  };
}

import { createHash } from "node:crypto";
import { lstat, mkdir, readFile, readdir, stat, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

import { UsageError } from "../evidence/index.js";
import { MAA_EVIDENCE_VERSION } from "../version.js";

/**
 * The host-agent Skill that ships inside this package.
 *
 * The Skill and the CLI are distributed separately, so a harness can end up reading a Skill that
 * describes a different MEK release than the one it runs. Everything here exists to make that
 * comparison cheap and local: the payload is read from this package rather than from the npm
 * registry, and every file carries a digest.
 *
 * The payload deliberately states no version of its own. A version written into `SKILL.md` would
 * have to be edited on every release, and it would still be wrong for a copy installed from the
 * repository rather than from a published tarball. Comparing bytes answers the question a reader
 * actually has - "is the copy in front of me the same one this CLI ships?" - and nothing in the
 * payload has to change when the package version does.
 */
export const PACKAGED_SKILL_NAME = "maa-evidence";
export const PACKAGED_SKILL_ENTRY = "SKILL.md";

export type PackagedSkillFile = {
  path: string;
  bytes: number;
  sha256: string;
};

export type PackagedSkill = {
  name: string;
  /** Version of the running package, which is what this payload was built from. */
  version: string;
  /** Absolute path of the packaged payload directory. */
  directory: string;
  entry: string;
  files: PackagedSkillFile[];
};

export type PackagedSkillInstall = {
  directory: string;
  installedDirectory: string;
  version: string;
  files: string[];
};

export type PackagedSkillFileStatus = "same" | "different" | "missing";

export type PackagedSkillCheck = {
  directory: string;
  installedDirectory: string;
  /** Version of the running package, which is the copy the comparison is against. */
  version: string;
  /** Whether an installed Skill directory exists at all. */
  installed: boolean;
  /** True when every packaged file exists with byte-identical content. */
  match: boolean;
  files: Array<{
    path: string;
    status: PackagedSkillFileStatus;
    /** Digest of the installed file, present when it could be read. */
    installedSha256?: string;
  }>;
  /**
   * Files in the installed directory that the payload does not ship, such as agent metadata. They
   * are reported but never make a copy count as different.
   */
  extraFiles: string[];
};

/**
 * The package root, from either `dist/skills/` (published) or `src/skills/` (tests, typecheck).
 * The Skill is published through `package.json#files`, so resolving it relative to this module keeps
 * `--print` and `--install` on exactly the copy the running build was packaged with.
 */
function packageRoot(): string {
  return path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..");
}

export function packagedSkillDirectory(root: string = packageRoot()): string {
  return path.join(root, "skills", PACKAGED_SKILL_NAME);
}

/**
 * List a payload directory.
 *
 * `reject` is for the packaged payload, which is ours and must stay plain files. `skip` is for a
 * copy someone else installed: an agent may add its own metadata or point an entry at a file
 * elsewhere, and a verification command must report that rather than fail with a filesystem error.
 */
async function collectFiles(
  directory: string,
  symlinks: "reject" | "skip" = "reject",
): Promise<string[]> {
  const entries = await readdir(directory, { withFileTypes: true, recursive: true });
  const files: string[] = [];
  for (const entry of entries) {
    const absolute = path.join(entry.parentPath, entry.name);
    const relative = path.relative(directory, absolute).split(path.sep).join("/");
    if (entry.isSymbolicLink()) {
      if (symlinks === "skip") continue;
      throw new Error(`The packaged Skill must not contain symbolic links: ${relative}`);
    }
    if (entry.isDirectory()) continue;
    if (!entry.isFile()) {
      if (symlinks === "skip") continue;
      throw new Error(`The packaged Skill contains an unsupported entry: ${relative}`);
    }
    files.push(relative);
  }
  return files.sort((left, right) => left.localeCompare(right));
}

/**
 * Create an install directory chain one level at a time, refusing to walk through a link.
 *
 * `mkdir(..., { recursive: true })` is happy to follow a pre-existing `references/` symlink, which
 * would place every write below it outside the directory the caller named.
 */
async function ensureInstallDirectories(root: string, segments: readonly string[]): Promise<void> {
  let current = root;
  for (const segment of segments) {
    current = path.join(current, segment);
    const metadata = await lstat(current).catch(() => undefined);
    if (metadata === undefined) {
      await mkdir(current);
      continue;
    }
    if (metadata.isSymbolicLink()) {
      throw new UsageError(`Refusing to write through a symbolic link: ${current}`);
    }
    if (!metadata.isDirectory()) {
      throw new UsageError(`The Skill install path is not a directory: ${current}`);
    }
  }
}

export async function loadPackagedSkill(directory: string = packagedSkillDirectory()): Promise<PackagedSkill> {
  const relativePaths = await collectFiles(directory);
  if (!relativePaths.includes(PACKAGED_SKILL_ENTRY)) {
    throw new Error(`The packaged Skill is missing ${PACKAGED_SKILL_ENTRY}: ${directory}`);
  }
  const files: PackagedSkillFile[] = [];
  for (const relativePath of relativePaths) {
    const content = await readFile(path.join(directory, ...relativePath.split("/")));
    files.push({
      path: relativePath,
      bytes: content.byteLength,
      sha256: createHash("sha256").update(content).digest("hex"),
    });
  }
  return {
    name: PACKAGED_SKILL_NAME,
    version: MAA_EVIDENCE_VERSION,
    directory,
    entry: PACKAGED_SKILL_ENTRY,
    files,
  };
}

export async function readPackagedSkillFile(skill: PackagedSkill, relativePath: string): Promise<string> {
  if (!skill.files.some((file) => file.path === relativePath)) {
    throw new UsageError(
      `Unknown Skill file: ${relativePath}. Available: ${skill.files.map((file) => file.path).join(", ")}.`,
    );
  }
  return readFile(path.join(skill.directory, ...relativePath.split("/")), "utf8");
}

/**
 * Resolve the installed copy that a caller-named directory refers to.
 *
 * Two forms name that copy and both are accepted: the root that holds Skill directories
 * (`~/.agents/skills`) and the installed copy itself (`~/.agents/skills/maa-evidence`, which is what
 * the payload's own `SKILL.md` tells a reader to check). A directory is the installed copy when its
 * basename is the Skill name and it holds the entry file at its root; anything else is read as a
 * root, so a directory named `maa-evidence` without `SKILL.md` still resolves to its child and
 * reports as not installed rather than comparing the wrong level against the payload. The basename
 * comparison follows the filesystem: Windows names are case-insensitive, so `MAA-EVIDENCE` there is
 * the same installed copy, while POSIX keeps the two apart. `stat` follows links on purpose, because
 * the `skills` CLI installs an agent target as a link to one canonical copy; refusing to write
 * through a link stays in `installPackagedSkill`, where writing happens.
 */
function sameSkillDirectoryName(actual: string, expected: string): boolean {
  return process.platform === "win32"
    ? actual.toLowerCase() === expected.toLowerCase()
    : actual === expected;
}

async function resolveInstalledDirectory(skill: PackagedSkill, directory: string): Promise<string> {
  const named = path.resolve(directory);
  if (sameSkillDirectoryName(path.basename(named), skill.name)) {
    const entry = await stat(path.join(named, skill.entry)).catch(() => undefined);
    if (entry?.isFile() === true) return directory;
  }
  return path.join(directory, skill.name);
}

/**
 * Write the packaged payload to the installed copy named by `directory`.
 *
 * The caller names the destination, so MEK never guesses an agent's Skill directory, and either form
 * is accepted: the skills root, where the payload lands in `<directory>/<skill name>/`, or the
 * installed copy itself, which is refreshed in place instead of gaining a nested copy. Both resolve
 * through `resolveInstalledDirectory`, so the path that is written is the same path `--check` judges.
 * Targets are checked with `lstat` first: following a symbolic link here would write outside the
 * chosen directory, which is the one thing an explicit install must not do.
 */
export async function installPackagedSkill(
  skill: PackagedSkill,
  directory: string,
): Promise<PackagedSkillInstall> {
  const installedDirectory = await resolveInstalledDirectory(skill, directory);
  const installedMetadata = await lstat(installedDirectory).catch(() => undefined);
  if (installedMetadata?.isSymbolicLink() === true) {
    throw new UsageError(`Refusing to install into a symbolic link: ${installedDirectory}`);
  }
  if (installedMetadata !== undefined && !installedMetadata.isDirectory()) {
    throw new UsageError(`The Skill install path is not a directory: ${installedDirectory}`);
  }
  await mkdir(installedDirectory, { recursive: true });
  const written: string[] = [];
  for (const file of skill.files) {
    const segments = file.path.split("/");
    const target = path.join(installedDirectory, ...segments);
    const targetMetadata = await lstat(target).catch(() => undefined);
    if (targetMetadata?.isSymbolicLink() === true) {
      throw new UsageError(`Refusing to overwrite a symbolic link: ${target}`);
    }
    if (targetMetadata?.isDirectory() === true) {
      throw new UsageError(`Refusing to overwrite a directory: ${target}`);
    }
    await ensureInstallDirectories(installedDirectory, segments.slice(0, -1));
    await writeFile(target, await readFile(path.join(skill.directory, ...segments)));
    written.push(file.path);
  }
  return {
    directory,
    installedDirectory,
    version: skill.version,
    files: written,
  };
}

/**
 * Compare an installed copy against the packaged payload.
 *
 * The caller names the directory, so MEK never guesses an agent's Skill path, and either form is
 * accepted: the skills root, where the copy is read from `<directory>/<skill name>/`, or the
 * installed copy itself, which is judged directly, so checking the directory the payload's own
 * `SKILL.md` names reports the same verdict as checking the root that holds it. `installedDirectory`
 * is the path actually judged. The comparison is a byte comparison rather than a version claim: a
 * copy that a release did not touch stays `same` even though the package version moved on. Directory
 * symlinks are followed, because the `skills` CLI installs agent directories as links to one
 * canonical copy; only writing refuses links.
 */
export async function checkPackagedSkill(
  skill: PackagedSkill,
  directory: string,
): Promise<PackagedSkillCheck> {
  const installedDirectory = await resolveInstalledDirectory(skill, directory);
  // `stat` follows links on purpose: the skills CLI installs an agent target as a link to one
  // canonical copy. A link to a file, a broken link, or a plain file reports as "not installed"
  // rather than surfacing a raw filesystem error for a path the caller merely named.
  const installedMetadata = await stat(installedDirectory).catch(() => undefined);
  const installed = installedMetadata?.isDirectory() === true;
  const files: PackagedSkillCheck["files"] = [];
  for (const file of skill.files) {
    const target = path.join(installedDirectory, ...file.path.split("/"));
    const content = installed ? await readFile(target).catch(() => undefined) : undefined;
    files.push({
      path: file.path,
      status: content === undefined
        ? "missing"
        : createHash("sha256").update(content).digest("hex") === file.sha256
          ? "same"
          : "different",
      ...(content === undefined
        ? {}
        : { installedSha256: createHash("sha256").update(content).digest("hex") }),
    });
  }
  const packaged = new Set(skill.files.map((file) => file.path));
  const extraFiles = installed
    ? (await collectFiles(installedDirectory, "skip")).filter((file) => !packaged.has(file))
    : [];
  return {
    directory,
    installedDirectory,
    version: skill.version,
    installed,
    match: installed && files.every((file) => file.status === "same"),
    files,
    extraFiles,
  };
}

import type { InspectionResult } from "../evidence/index.js";

import { renderJson } from "./json.js";
import { renderMermaid } from "./mermaid.js";
import { renderText } from "./text.js";

export type ViewFormat = "json" | "text" | "mermaid";

export type ViewOptions = {
  format?: ViewFormat;
  pretty?: boolean;
};

export function view(result: InspectionResult, options: ViewOptions = {}): string {
  switch (options.format ?? "text") {
    case "json":
      return renderJson(result, options.pretty ?? true);
    case "text":
      return renderText(result);
    case "mermaid":
      return renderMermaid(result);
  }
}

